<?php

namespace Medoo\Tests;

use Medoo\Medoo;
use PDO;
use PHPUnit\Framework\Attributes\DataProvider;

#[\PHPUnit\Framework\Attributes\CoversClass(\Medoo\Medoo::class)]
class CreateTest extends MedooTestCase
{
    #[DataProvider('identityTypesProvider')]
    public function testCreateWithIdentity(string $type, string $expected): void
    {
        $this->setType($type);

        $this->database->create("account", [
            "@id",
            "email" => ["VARCHAR(70)", "NOT NULL"],
            "UNIQUE (<email>)"
        ]);

        $this->assertQuery($expected, $this->database->queryString);
    }

    /** @return array<string, array{string, string}> */
    public static function identityTypesProvider(): array
    {
        return [
            'MySQL' => [
                'mysql',
                'CREATE TABLE IF NOT EXISTS "account" ("id" BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, "email" VARCHAR(70) NOT NULL, UNIQUE ("email"))'
            ],
            'MariaDB' => [
                'mariadb',
                'CREATE TABLE IF NOT EXISTS "account" ("id" BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, "email" VARCHAR(70) NOT NULL, UNIQUE ("email"))'
            ],
            'PostgreSQL' => [
                'pgsql',
                'CREATE TABLE IF NOT EXISTS "account" ("id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "email" VARCHAR(70) NOT NULL, UNIQUE ("email"))'
            ],
            'SQLite' => [
                'sqlite',
                'CREATE TABLE IF NOT EXISTS "account" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "email" VARCHAR(70) NOT NULL, UNIQUE ("email"))'
            ],
            'MSSQL' => [
                'mssql',
                'CREATE TABLE "account" ("id" BIGINT IDENTITY(1,1) PRIMARY KEY, "email" VARCHAR(70) NOT NULL, UNIQUE ("email"))'
            ],
            'Oracle' => [
                'oracle',
                'CREATE TABLE "account" ("id" NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "email" VARCHAR(70) NOT NULL, UNIQUE ("email"))'
            ],
            'Sybase' => [
                'sybase',
                'CREATE TABLE "account" ("id" BIGINT IDENTITY PRIMARY KEY, "email" VARCHAR(70) NOT NULL, UNIQUE ("email"))'
            ]
        ];
    }

    public function testCreateWithCustomIdentityColumn(): void
    {
        $this->setType('pgsql');

        $this->database->create('account', [
            '@account_id',
            'name' => 'VARCHAR(100) NOT NULL'
        ]);

        $this->assertQuery(
            'CREATE TABLE IF NOT EXISTS "account" ("account_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "name" VARCHAR(100) NOT NULL)',
            $this->database->queryString
        );
    }

    #[DataProvider('invalidIdentityProvider')]
    public function testCreateRejectsInvalidIdentity(string $identity): void
    {
        $this->setType('pgsql');
        $this->expectException(\InvalidArgumentException::class);
        $this->expectExceptionMessage("Invalid identity column supplied: {$identity}.");

        $this->database->create('account', [$identity]);
    }

    /** @return array<string, array{string}> */
    public static function invalidIdentityProvider(): array
    {
        return [
            'empty name' => ['@'],
            'leading digit' => ['@1id'],
            'qualified name' => ['@public.id'],
            'whitespace' => ['@account id'],
            'trailing newline' => ["@id\n"]
        ];
    }

    public function testCreateRejectsMultipleIdentityColumns(): void
    {
        $this->setType('pgsql');
        $this->expectException(\InvalidArgumentException::class);
        $this->expectExceptionMessage('Multiple identity columns supplied.');

        $this->database->create('account', ['@id', '@other_id']);
    }

    /** @param array<array-key, string> $columns */
    #[DataProvider('identityCollisionProvider')]
    public function testCreateRejectsIdentityColumnCollision(array $columns): void
    {
        $this->setType('pgsql');
        $this->expectException(\InvalidArgumentException::class);
        $this->expectExceptionMessage('Identity column id is already defined.');

        $this->database->create('account', $columns);
    }

    /** @return array<string, array{array<array-key, string>}> */
    public static function identityCollisionProvider(): array
    {
        return [
            'identity first' => [['@id', 'id' => 'BIGINT']],
            'identity last' => [['id' => 'BIGINT', '@id']]
        ];
    }

    public function testCreateRejectsIdentityForUnsupportedDatabase(): void
    {
        $this->setType('custom');
        $this->expectException(\InvalidArgumentException::class);
        $this->expectExceptionMessage('Identity columns are not supported for database type custom.');

        $this->database->create('account', ['@id']);
    }

    public function testSQLiteIdentityExecution(): void
    {
        if (!in_array('sqlite', PDO::getAvailableDrivers(), true)) {
            $this->markTestSkipped('The pdo_sqlite extension is not available.');
        }

        $database = new Medoo([
            'type' => 'sqlite',
            'database' => ':memory:',
            'error' => PDO::ERRMODE_EXCEPTION
        ]);

        $database->create('account', [
            '@id',
            'name' => 'TEXT NOT NULL'
        ]);
        $database->insert('account', ['name' => 'foo']);

        $this->assertSame('1', $database->id());
        $this->assertSame(1, $database->get('account', 'id [Int]'));
    }

    #[\PHPUnit\Framework\Attributes\DataProviderExternal(MedooTestCase::class, 'typesProvider')]
    public function testCreate(string $type): void
    {
        $this->setType($type);

        $this->database->create("account", [
            "id" => [
                "INT",
                "NOT NULL",
                "AUTO_INCREMENT"
            ],
            "email" => [
                "VARCHAR(70)",
                "NOT NULL",
                "UNIQUE"
            ],
            "PRIMARY KEY (<id>)"
        ], [
            "AUTO_INCREMENT" => 200
        ]);

        $this->assertQuery(
            [
            'default' => <<<EOD
                CREATE TABLE IF NOT EXISTS "account"
                ("id" INT NOT NULL AUTO_INCREMENT,
                "email" VARCHAR(70) NOT NULL UNIQUE,
                PRIMARY KEY ("id"))
                AUTO_INCREMENT = 200
                EOD,
            'mssql' => <<<EOD
                CREATE TABLE [account]
                ([id] INT NOT NULL AUTO_INCREMENT,
                [email] VARCHAR(70) NOT NULL UNIQUE,
                PRIMARY KEY ([id]))
                AUTO_INCREMENT = 200
                EOD,
            'oracle' => <<<EOD
                CREATE TABLE "account"
                ("id" INT NOT NULL AUTO_INCREMENT,
                "email" VARCHAR(70) NOT NULL UNIQUE,
                PRIMARY KEY ("id"))
                AUTO_INCREMENT = 200
                EOD
        ],
            $this->database->queryString
        );
    }

    #[\PHPUnit\Framework\Attributes\DataProviderExternal(MedooTestCase::class, 'typesProvider')]
    public function testCreateWithStringDefinition(string $type): void
    {
        $this->setType($type);

        $this->database->create("account", [
            "id" => "INT NOT NULL AUTO_INCREMENT",
            "email" => "VARCHAR(70) NOT NULL UNIQUE"
        ]);

        $this->assertQuery(
            [
            'default' => <<<EOD
                CREATE TABLE IF NOT EXISTS "account"
                ("id" INT NOT NULL AUTO_INCREMENT,
                "email" VARCHAR(70) NOT NULL UNIQUE)
                EOD,
            'mssql' => <<<EOD
                CREATE TABLE [account]
                ([id] INT NOT NULL AUTO_INCREMENT,
                [email] VARCHAR(70) NOT NULL UNIQUE)
                EOD,
            'oracle' => <<<EOD
                CREATE TABLE "account"
                ("id" INT NOT NULL AUTO_INCREMENT,
                "email" VARCHAR(70) NOT NULL UNIQUE)
                EOD
        ],
            $this->database->queryString
        );
    }

    #[\PHPUnit\Framework\Attributes\DataProviderExternal(MedooTestCase::class, 'typesProvider')]
    public function testCreateWithSingleOption(string $type): void
    {
        $this->setType($type);

        $this->database->create("account", [
            "id" => [
                "INT",
                "NOT NULL",
                "AUTO_INCREMENT"
            ],
            "email" => [
                "VARCHAR(70)",
                "NOT NULL",
                "UNIQUE"
            ]
        ], "TABLESPACE tablespace_name");

        $this->assertQuery(
            [
            'default' => <<<EOD
                CREATE TABLE IF NOT EXISTS "account"
                ("id" INT NOT NULL AUTO_INCREMENT,
                "email" VARCHAR(70) NOT NULL UNIQUE)
                TABLESPACE tablespace_name
                EOD,
            'mssql' => <<<EOD
                CREATE TABLE [account]
                ([id] INT NOT NULL AUTO_INCREMENT,
                [email] VARCHAR(70) NOT NULL UNIQUE)
                TABLESPACE tablespace_name
                EOD,
            'oracle' => <<<EOD
                CREATE TABLE "account"
                ("id" INT NOT NULL AUTO_INCREMENT,
                "email" VARCHAR(70) NOT NULL UNIQUE)
                TABLESPACE tablespace_name
                EOD
        ],
            $this->database->queryString
        );
    }
}
